Heard.declaration:
export interface Heard {
  readonly items: SessionItem[]
  readonly gone: string[]
  readonly signals: Signal[]
}

Signal.declaration:
export type Signal =
  | {
      readonly kind: 'started'
      readonly session: string
      readonly model?: string
      readonly reasoning?: ReasoningEffort
      readonly key: boolean

      readonly mode?: string

      readonly commands?: readonly string[]
    }

  | { readonly kind: 'doing'; readonly what: string }
  | { readonly kind: 'said'; readonly text: string }
  | { readonly kind: 'retry'; readonly text: string | undefined }

  | { readonly kind: 'writing'; readonly paths: readonly string[] }

  | { readonly kind: 'asks'; readonly ask: string; readonly wanted: Wanted; readonly line?: string }
  | { readonly kind: 'resolved'; readonly ask: string }

  | { readonly kind: 'mode'; readonly mode: string }
  | { readonly kind: 'model'; readonly model: string }
  | { readonly kind: 'reasoning'; readonly effort: ReasoningEffort }

  | ({ readonly kind: 'spend' } & SessionSpend)
  | { readonly kind: 'usage'; readonly usage: ProviderUsage }

  | { readonly kind: 'plan'; readonly plan: PlanUsage }

  | { readonly kind: 'task'; readonly task: BackgroundTask }

  | { readonly kind: 'begun' }

  | { readonly kind: 'held'; readonly hook: string; readonly reason: string }
  | { readonly kind: 'goal'; readonly goal: SessionGoal | undefined; readonly status?: 'active' | 'paused' | 'blocked' | 'usageLimited' | 'budgetLimited' | 'complete' }
  | {
      readonly kind: 'ended'

      readonly how: 'done' | 'stopped' | 'failed' | 'blocked' | 'limit' | 'signedOut' | 'offPlan'
      readonly text?: string

      readonly resetsAt?: number
    }

Conversation.declaration:
