Wanted.declaration:
export type Wanted =
  | ({ readonly kind: 'elicitation' } & Elicitation)
  | { readonly kind: 'write'; readonly paths: readonly string[] }
  | { readonly kind: 'command'; readonly command: string }
  | { readonly kind: 'web'; readonly url: string }
  | { readonly kind: 'read'; readonly path: string }
  | { readonly kind: 'question'; readonly question: string; readonly choices: readonly string[] }
  | { readonly kind: 'start'; readonly plan: string }
  | { readonly kind: 'other'; readonly tool: string; readonly detail: string }

SessionItem.declaration:
export type SessionItem =
  | {
      readonly kind: 'mine'
      readonly id: string
      readonly text: string
      readonly images?: readonly SessionImage[]

      readonly unsent?: boolean

      readonly at?: number
    }
  | { readonly kind: 'theirs'; readonly id: string; readonly text: string; readonly at?: number; readonly phase?: 'commentary' | 'final_answer' }
  | {
      readonly kind: 'did'
      readonly id: string

      readonly what: string

      readonly detail?: string

      readonly path?: string
      readonly live?: boolean

      readonly lasting?: boolean

      readonly images?: readonly SessionImage[]
    }
  | { readonly kind: 'thought'; readonly id: string; readonly text: string }
  | {

      readonly kind: 'shell'
      readonly id: string
      readonly command: string

      readonly output: string
      readonly running?: boolean

      readonly code?: number
      readonly stopped?: boolean

      readonly terminal?: boolean
      readonly at?: number
    }
  | { readonly kind: 'card'; readonly id: string; readonly card: SessionCard }
  | { readonly kind: 'wrote'; readonly id: string; readonly paths: readonly string[] }
  | {
      readonly kind: 'note'
      readonly id: string
      readonly note: 'stopped' | 'limit' | 'failed' | 'summarised' | 'mode' | 'task' | 'goal'
      readonly text: string

      readonly detail?: string
    }

  | {
      readonly kind: 'request'
      readonly id: string

      readonly app?: string
      readonly tasks: readonly RequestTask[]
      readonly answer?: RequestAnswer
    }

  | {
      readonly kind: 'team-request'
      readonly id: string

      readonly lines: readonly string[]
      readonly answer?: TeamAnswer
    }

  | {
      readonly kind: 'steps'

      readonly id: string
      readonly ids: readonly string[]

      readonly latest?: string

      readonly images?: readonly SessionImage[]
    }

